#!/usr/bin/env node
// Condense a captured conversation JSONL: human turns, tool-call census, wall-clock.
// usage: node condense.mjs <file.jsonl> [--full]
import { readFileSync } from 'node:fs';

const [file, ...rest] = process.argv.slice(2);
const full = rest.includes('--full');
const lines = readFileSync(file, 'utf8').split('\n').filter(Boolean);

const textOf = (m) => {
  if (!m) return '';
  const c = m.content;
  if (typeof c === 'string') return c;
  if (!Array.isArray(c)) return '';
  return c.filter((b) => b.type === 'text').map((b) => b.text).join('\n');
};

let first = null, last = null;
const humans = [];
const tools = new Map();
let assistantTexts = [];
for (const l of lines) {
  let e; try { e = JSON.parse(l); } catch { continue; }
  const ts = e.timestamp || e.ts;
  if (ts) { first ??= ts; last = ts; }
  const m = e.message || e;
  const role = e.type || m.role;
  if (role === 'user') {
    const c = m.content;
    const isToolResult = Array.isArray(c) && c.some((b) => b.type === 'tool_result');
    if (!isToolResult) {
      const t = textOf(m).trim();
      if (t) humans.push({ ts, t });
    }
  } else if (role === 'assistant') {
    const c = m.content;
    if (Array.isArray(c)) for (const b of c) {
      if (b.type === 'tool_use') tools.set(b.name, (tools.get(b.name) || 0) + 1);
    }
    const t = textOf(m).trim();
    if (t) assistantTexts.push({ ts, t });
  }
}

const mins = first && last ? ((new Date(last) - new Date(first)) / 60000).toFixed(1) : '?';
console.log(`== ${file.split('/').pop()}`);
console.log(`entries=${lines.length} wall=${mins}min first=${first} last=${last}`);
console.log(`tools: ${[...tools.entries()].sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k}:${v}`).join(' ')}`);
console.log(`-- human turns (${humans.length}):`);
for (const h of humans) {
  const t = full ? h.t : h.t.slice(0, 700);
  console.log(`  [${h.ts}] ${t.replace(/\n/g, '\n    ')}`);
}
if (full) {
  console.log(`-- assistant texts (${assistantTexts.length}):`);
  for (const a of assistantTexts) console.log(`  [${a.ts}] ${a.t.slice(0, 1500).replace(/\n/g, '\n    ')}`);
}

