#!/usr/bin/env node
// Census of how a captured session edited tracked files: Edit/Write/NotebookEdit calls
// vs. Bash commands that write a repo path (heredoc redirect, sed -i, tee, python open(w)).
import { readFileSync } from 'node:fs';

const WRITEY = /(^|[\s;&|])(sed\s+-i|tee\s|patch\s|perl\s+-i|python3?\s+-\s*<<|cat\s*>|cat\s*<<'?EOF'?\s*>|applypatch)|>\s*(packs|engine|docs|\.claudinite|\.github|dev)\//;

for (const file of process.argv.slice(2)) {
  const lines = readFileSync(file, 'utf8').split('\n').filter(Boolean);
  let fileTool = 0; const bashWrites = [];
  for (const l of lines) {
    let e; try { e = JSON.parse(l); } catch { continue; }
    const m = e.message || e;
    if ((e.type || m.role) !== 'assistant' || !Array.isArray(m.content)) continue;
    for (const b of m.content) {
      if (b.type !== 'tool_use') continue;
      if (b.name === 'Edit' || b.name === 'Write' || b.name === 'NotebookEdit') fileTool++;
      if (b.name === 'Bash') {
        const cmd = String(b.input?.command ?? '');
        if (WRITEY.test(cmd)) bashWrites.push(cmd.replace(/\n/g, ' ⏎ ').slice(0, 160));
      }
    }
  }
  console.log(`${file.split('/').pop().slice(0, 34)}  fileTool=${fileTool} bashWrites=${bashWrites.length}`);
  for (const c of bashWrites.slice(0, 6)) console.log(`    $ ${c}`);
}

