#!/usr/bin/env node
// Tune the shell-write guard against every real Bash command in the window's captures.
import { readFileSync, readdirSync } from 'node:fs';

const RE = new RegExp(process.argv[2]);
const dir = process.argv[3];
const cmds = [];
for (const f of readdirSync(dir)) {
  if (!f.endsWith('.jsonl')) continue;
  for (const l of readFileSync(`${dir}/${f}`, 'utf8').split('\n')) {
    if (!l) continue;
    let e; try { e = JSON.parse(l); } catch { continue; }
    const m = e.message || e;
    if ((e.type || m.role) !== 'assistant' || !Array.isArray(m.content)) continue;
    for (const b of m.content) {
      if (b.type === 'tool_use' && (b.name === 'Bash' || b.name === 'Monitor')) cmds.push([f, String(b.input?.command ?? '')]);
    }
  }
}
